SELECT toStartOfHour(time) AS hr, AVG(value_1) AS value_1, AVG(value_2) AS value_2, AVG(value_3) AS value_3, AVG(value_4) AS value_4 FROM (SELECT time, CAST(metric_0001 AS DOUBLE PRECISION) AS value_1, CAST(metric_0002 AS DOUBLE PRECISION) AS value_2, CAST(metric_0003 AS DOUBLE PRECISION) AS value_3, CAST(metric_0004 AS DOUBLE PRECISION) AS value_4 FROM wide5000) s GROUP BY toStartOfHour(time) ORDER BY hr
